CREATE INDEX IF NOT EXISTS business_team_member_lookup_idx ON public.business_team_members USING btree (member_user_id);
CREATE INDEX IF NOT EXISTS idx_conversations_participant_one ON public.conversations USING btree (participant_one);
CREATE INDEX IF NOT EXISTS idx_conversations_participant_two ON public.conversations USING btree (participant_two);
CREATE UNIQUE INDEX IF NOT EXISTS exchange_proposals_one_accepted_per_offered_listing_idx ON public.exchange_proposals USING btree (offered_listing_id) WHERE ((status = 'accepted'::text) AND (offered_listing_id IS NOT NULL));
CREATE UNIQUE INDEX IF NOT EXISTS exchange_proposals_one_accepted_per_target_idx ON public.exchange_proposals USING btree (listing_id) WHERE (status = 'accepted'::text);
CREATE INDEX IF NOT EXISTS idx_exchange_proposals_listing_id ON public.exchange_proposals USING btree (listing_id);
CREATE INDEX IF NOT EXISTS idx_exchange_proposals_offered_listing_id ON public.exchange_proposals USING btree (offered_listing_id);
CREATE INDEX IF NOT EXISTS idx_exchange_proposals_sender_id ON public.exchange_proposals USING btree (sender_id);
CREATE INDEX IF NOT EXISTS exchange_reviews_reviewed_user_created_idx ON public.exchange_reviews USING btree (reviewed_user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS exchange_reviews_reviewer_id_idx ON public.exchange_reviews USING btree (reviewer_id);
CREATE INDEX IF NOT EXISTS idx_favorites_listing_id ON public.favorites USING btree (listing_id);
CREATE INDEX IF NOT EXISTS idx_listing_promotions_plan_code ON public.listing_promotions USING btree (plan_code);
CREATE INDEX IF NOT EXISTS listing_promotions_listing_status_idx ON public.listing_promotions USING btree (listing_id, status, ends_at DESC);
CREATE INDEX IF NOT EXISTS listing_promotions_user_created_idx ON public.listing_promotions USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS listing_views_listing_viewed_at_idx ON public.listing_views USING btree (listing_id, viewed_at DESC);
CREATE INDEX IF NOT EXISTS listing_views_viewer_viewed_at_idx ON public.listing_views USING btree (viewer_id, viewed_at DESC) WHERE (viewer_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_listings_user_id ON public.listings USING btree (user_id);
CREATE INDEX IF NOT EXISTS listings_category_idx ON public.listings USING btree (category);
CREATE INDEX IF NOT EXISTS listings_city_idx ON public.listings USING btree (city);
CREATE INDEX IF NOT EXISTS listings_status_created_idx ON public.listings USING btree (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_messages_conversation_id ON public.messages USING btree (conversation_id);
CREATE INDEX IF NOT EXISTS idx_messages_sender_id ON public.messages USING btree (sender_id);
CREATE INDEX IF NOT EXISTS messages_conversation_sender_read_idx ON public.messages USING btree (conversation_id, sender_id, read_at, created_at);
CREATE INDEX IF NOT EXISTS idx_monetization_orders_listing_id ON public.monetization_orders USING btree (listing_id);
CREATE INDEX IF NOT EXISTS idx_monetization_orders_plan_code ON public.monetization_orders USING btree (plan_code);
CREATE INDEX IF NOT EXISTS idx_monetization_orders_proposal_id ON public.monetization_orders USING btree (proposal_id);
CREATE UNIQUE INDEX IF NOT EXISTS monetization_orders_one_open_per_user_plan_listing ON public.monetization_orders USING btree (user_id, plan_code, COALESCE(listing_id, '00000000-0000-0000-0000-000000000000'::uuid)) WHERE (status = ANY (ARRAY['pending'::text, 'requires_action'::text]));
CREATE UNIQUE INDEX IF NOT EXISTS monetization_orders_pending_user_plan_listing_uidx ON public.monetization_orders USING btree (user_id, plan_code, COALESCE(listing_id, '00000000-0000-0000-0000-000000000000'::uuid)) WHERE ((status = ANY (ARRAY['pending'::text, 'requires_action'::text])) AND (plan_code IS NOT NULL));
CREATE INDEX IF NOT EXISTS monetization_orders_provider_payment_idx ON public.monetization_orders USING btree (provider, provider_payment_id) WHERE (provider_payment_id IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS monetization_orders_provider_payment_unique_idx ON public.monetization_orders USING btree (provider, provider_payment_id) WHERE (provider_payment_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS monetization_orders_user_created_idx ON public.monetization_orders USING btree (user_id, created_at DESC);
