CREATE INDEX IF NOT EXISTS idx_notifications_conversation_id ON public.notifications USING btree (conversation_id);
CREATE INDEX IF NOT EXISTS idx_notifications_listing_id ON public.notifications USING btree (listing_id);
CREATE INDEX IF NOT EXISTS idx_notifications_proposal_id ON public.notifications USING btree (proposal_id);
CREATE INDEX IF NOT EXISTS notifications_user_created_idx ON public.notifications USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS payment_webhook_events_order_id_idx ON public.payment_webhook_events USING btree (order_id);
CREATE INDEX IF NOT EXISTS payment_webhook_events_status_idx ON public.payment_webhook_events USING btree (processing_status, received_at DESC);
CREATE INDEX IF NOT EXISTS promotion_credit_wallets_user_active_idx ON public.promotion_credit_wallets USING btree (user_id, ends_at DESC);
