CREATE INDEX IF NOT EXISTS idx_reports_reported_user_id ON public.reports USING btree (reported_user_id);
CREATE INDEX IF NOT EXISTS idx_reports_reporter_id ON public.reports USING btree (reporter_id);
CREATE INDEX IF NOT EXISTS saved_searches_user_active_idx ON public.saved_searches USING btree (user_id, is_active);
CREATE INDEX IF NOT EXISTS support_tickets_user_created_idx ON public.support_tickets USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_user_hidden_conversations_conversation_id ON public.user_hidden_conversations USING btree (conversation_id);
CREATE INDEX IF NOT EXISTS idx_user_hidden_exchange_proposals_proposal_id ON public.user_hidden_exchange_proposals USING btree (proposal_id);
